import Foundation
import XCTest
@testable import Hardwood

/// The golden fixtures in `ios/NBAStatsTests/Fixtures/` are generated by the backend from the
/// same contract the Swift types are written against, so decoding them is the one test that
/// actually proves the two sides agree.
///
/// Every test here also asserts against the payload type's own `preview` value, so a missing
/// fixture directory turns the suite into a skip plus a set of still-meaningful assertions rather
/// than a green run that proved nothing.
final class PayloadDecodingTests: XCTestCase {

    private let decoder = APIClient.makeDecoder()

    private func requireFixtures() throws {
        try XCTSkipUnless(TestBundles.hasWidgetFixtures, """
            No golden fixtures are in a test-visible bundle. They are generated by the backend \
            into contracts/fixtures/ and copied to ios/NBAStatsTests/Fixtures/ by \
            scripts/sync_contracts.sh; run that and add the folder to the HardwoodTests target.
            """)
    }

    private func fixture(_ name: String) throws -> Data {
        try XCTUnwrap(TestBundles.fixtureData(named: name), "\(name).json is not in any test bundle")
    }

    // MARK: - Every widget fixture decodes into its payload type

    func testEveryWidgetKindHasAFixtureThatDecodes() throws {
        try requireFixtures()
        var decoded: [WidgetKind: WidgetPayload] = [:]
        for kind in WidgetKind.allCases {
            let data = try fixture("widget_\(kind.rawValue)")
            let payload = try WidgetPayload.decode(kind: kind, from: data, using: decoder)
            XCTAssertEqual(payload.kind, kind, "widget_\(kind.rawValue).json decoded into the wrong case")
            decoded[kind] = payload
        }
        XCTAssertEqual(decoded.count, WidgetKind.allCases.count)
        XCTAssertEqual(decoded.count, 12)
    }

    /// A payload that decodes has to survive being written to the disk cache and read back, which
    /// is exactly an encode/decode round trip through the same coders the app uses.
    func testEveryWidgetFixtureSurvivesARoundTrip() throws {
        try requireFixtures()
        let encoder = APIClient.makeEncoder()
        for kind in WidgetKind.allCases {
            let data = try fixture("widget_\(kind.rawValue)")
            let payload = try WidgetPayload.decode(kind: kind, from: data, using: decoder)
            let reEncoded = try encoder.encode(payload)
            let again = try WidgetPayload.decode(kind: kind, from: reEncoded, using: decoder)
            XCTAssertEqual(again, payload, "\(kind.rawValue) changed on the way through the cache")
        }
    }

    // MARK: - Per-kind content

    func testStatTileFixture() throws {
        try requireFixtures()
        let payload = try decoder.decode(StatTilePayload.self, from: try fixture("widget_stat_tile"))
        XCTAssertFalse(payload.subject.displayName.isEmpty)
        XCTAssertFalse(payload.primary.metric.isEmpty)
        XCTAssertFalse(payload.primary.displayValue.isEmpty)
        XCTAssertFalse(payload.sparkline.isEmpty)
        // And the preview agrees on the shape, so this test says something even with no fixture.
        XCTAssertEqual(StatTilePayload.preview.primary.metric, "ts_pct")
        XCTAssertFormatted(StatTilePayload.preview.primary.displayValue, "61.5%")
    }

    func testPlayerSnapshotFixture() throws {
        try requireFixtures()
        let payload = try decoder.decode(PlayerSnapshotPayload.self, from: try fixture("widget_player_snapshot"))
        XCTAssertGreaterThan(payload.player.playerId, 0)
        XCTAssertFalse(payload.metrics.isEmpty)
        XCTAssertFalse(PlayerSnapshotPayload.preview.metrics.isEmpty)
    }

    func testLeaderboardFixture() throws {
        try requireFixtures()
        let payload = try decoder.decode(LeaderboardPayload.self, from: try fixture("widget_leaderboard"))
        XCTAssertFalse(payload.rows.isEmpty)
        XCTAssertFalse(payload.metric.key.isEmpty)
        XCTAssertEqual(payload.rows.first?.rank, 1, "The leaderboard does not start at rank 1")
        // Ranks ascend, and every row names a subject.
        XCTAssertEqual(payload.rows.map { $0.rank }, payload.rows.map { $0.rank }.sorted())
        for row in payload.rows {
            XCTAssertFalse(row.subjectName.isEmpty)
            XCTAssertFalse(row.id.isEmpty)
        }
        XCTAssertEqual(LeaderboardPayload.preview.metric.key, "ts_pct")
        XCTAssertFalse(LeaderboardPayload.preview.rows.isEmpty)
    }

