        let payload = try decoder.decode(TrendChartPayload.self, from: try fixture("widget_trend_chart"))
        XCTAssertFalse(payload.series.isEmpty)
        let points = payload.series.flatMap { $0.points }
        XCTAssertFalse(points.isEmpty)
        // A point with no value is a real case: it must survive as nil, not become zero.
        for point in points {
            XCTAssertFalse(point.x.isEmpty)
            if let y = point.y { XCTAssertTrue(y.isFinite) }
        }
        XCTAssertFalse(TrendChartPayload.preview.series.isEmpty)
    }

