    func testCareerArcFixture() throws {
        try requireFixtures()
        let payload = try decoder.decode(CareerArcPayload.self, from: try fixture("widget_career_arc"))
        XCTAssertFalse(payload.seasons.isEmpty)
        XCTAssertFalse(payload.metric.key.isEmpty)
        for season in payload.seasons {
            XCTAssertFalse(season.season.isEmpty)
            // The era rule at the payload level: an unavailable season carries no number.
            if season.availability == .unavailable {
                XCTAssertNil(season.value, "\(season.season) is unavailable but still carries a value")
            }
        }
        XCTAssertFalse(CareerArcPayload.preview.seasons.isEmpty)
    }

    // MARK: - The previews are real payloads

    /// Every `preview` is a payload the views render in Xcode, so it has to satisfy the same
    /// invariants a decoded one does — including the em-dash rule.
    func testEveryPreviewPayloadIsWellFormed() throws {
        let encoder = APIClient.makeEncoder()
        for kind in WidgetKind.allCases {
            let payload = WidgetPayload.preview(for: kind)
            XCTAssertEqual(payload.kind, kind)
            // A preview must also round-trip, since the cache stores previews in demo mode.
            let data = try encoder.encode(payload)
            let decoded = try WidgetPayload.decode(kind: kind, from: data, using: decoder)
            XCTAssertEqual(decoded, payload, "\(kind.rawValue).preview did not round-trip")
        }
    }

    func testAnUnavailableMetricValueNeverCarriesANumber() {
        XCTAssertNil(MetricValue.previewUnavailable.value)
        XCTAssertEqual(MetricValue.previewUnavailable.displayValue, Formatting.emDash)
        XCTAssertEqual(MetricValue.previewUnavailable.availability, .unavailable)
        XCTAssertTrue(MetricValue.previewUnavailable.isMissing)
        XCTAssertFalse(MetricValue.preview.isMissing)
    }

