    // MARK: - The resolve envelope

    /// The endpoint the whole dashboard is built on: one response, one typed payload per widget,
    /// each decoded according to its own `kind`.
    func testDashboardResolveFixtureDecodesEveryResult() throws {
        try requireFixtures()
        let response = try decoder.decode(DashboardResolveResponse.self, from: try fixture("dashboard_resolve"))
        XCTAssertFalse(response.results.isEmpty)
        XCTAssertNotNil(response.syncVersion)
        XCTAssertNotNil(response.dataThrough)
        XCTAssertNotNil(response.resolvedContext)

        var kindsSeen: Set<WidgetKind> = []
        for result in response.results {
            XCTAssertFalse(result.widgetId.isEmpty)
            let kind = try XCTUnwrap(result.kind, "Unknown widget kind \"\(result.kindRaw)\"")
            kindsSeen.insert(kind)
            XCTAssertNil(result.decodeError,
                         "\(result.widgetId) (\(result.kindRaw)) did not decode: \(result.decodeError ?? "")")
            switch result.effectiveStatus {
            case .ok, .partial:
                let payload = try XCTUnwrap(result.payload, "\(result.widgetId) has no payload")
                XCTAssertEqual(payload.kind, kind)
            case .unchanged:
                XCTAssertNil(result.payload)
            case .error:
                XCTAssertNotNil(result.failureMessage)
            }
        }
        XCTAssertEqual(kindsSeen, Set(WidgetKind.allCases),
                       "The resolve fixture does not exercise every widget kind")
        XCTAssertEqual(response.resultsByWidgetID.count, response.results.count)
    }

    /// The failure branch of `ResolveResult.init(from:)` — the app's most intricate decoder.
    ///
    /// `contracts/CONTRACT.md` §3 documents a per-widget failure as `status: "error"` with a
    /// populated `error` body and a `null` payload. The resolve fixture carries one on purpose
    /// (`ERROR_WIDGET_CONFIGS` in `nbastats.fixtures_export`: a leaderboard on a metric the era
    /// never recorded, which the service answers with `metric_unavailable`). Without it every
    /// result in every fixture was `ok` or `partial` and this branch had no golden coverage.
    func testDashboardResolveFixtureCarriesAFailedWidget() throws {
        try requireFixtures()
        let response = try decoder.decode(DashboardResolveResponse.self,
                                          from: try fixture("dashboard_resolve"))

        let failures = response.results.filter { $0.effectiveStatus == .error }
        XCTAssertEqual(failures.count, 1,
                       "The resolve fixture must exercise exactly one failed widget")
        let failure = try XCTUnwrap(failures.first)

        XCTAssertNil(failure.payload, "An error result must not carry a payload")
        XCTAssertNil(failure.decodeError, "A well-formed error result is not a decoding failure")
        XCTAssertNotNil(failure.failureMessage)

        let body = try XCTUnwrap(failure.error, "An error result must carry the §7 error body")
        XCTAssertEqual(body.code, APIError.Code.metricUnavailable.rawValue)
        XCTAssertFalse(body.message.isEmpty, "An error body must say something a reader can act on")
        XCTAssertEqual(body.field, "metric")

        // And what the tile becomes: a metric the era never had reads as "unavailable", not as a
        // failure the reader should retry (ARCHITECTURE.md §3 rule 1).
        let error = APIError(body: body, status: 200)
        XCTAssertEqual(error.contractCode, .metricUnavailable)
        XCTAssertFalse(error.userMessage.isEmpty)
    }

    /// The era-honest half of the resolve fixture: results that carry notes, an estimate, or a
    /// stat the season never had.
    func testResolveFixtureCarriesTheEraCases() throws {
        try requireFixtures()
        let response = try decoder.decode(DashboardResolveResponse.self, from: try fixture("dashboard_resolve"))
        let flagged = response.results.filter { ($0.availability ?? .full) != .full }
        XCTAssertFalse(flagged.isEmpty, "The fixture exercises no era caveats at all")
        for result in flagged {
            XCTAssertFalse(result.notes.isEmpty,
                           "\(result.widgetId) is flagged \(result.availability?.rawValue ?? "?") but explains nothing")
        }
        XCTAssertTrue(response.results.contains { $0.availability == .unavailable },
                      "No result in the fixture is era-unavailable")
        XCTAssertTrue(response.results.contains { $0.availability == .estimated },
                      "No result in the fixture is an estimate")
    }

    /// A result whose `kind` this build does not know degrades to one failed tile, and never to a
    /// thrown decode that costs the reader the rest of the dashboard.
    func testAnUnknownKindDegradesToASingleFailedResult() throws {
        let json = """
        {"syncVersion": 1, "dataThrough": "2026-01-02", "results": [
          {"widgetId": "w1", "kind": "stat_tile", "status": "ok", "payload": {
             "subject": {"type": "player", "player": {"playerId": 2544, "name": "LeBron James"}, "team": null},
             "context": "2025-26 · Regular Season · Per Game",
             "primary": {"metric": "ts_pct", "value": 0.6153, "displayValue": "61.5%", "availability": "full"},
             "secondary": [], "sparkline": [], "sparklineMetric": "ts_pct"
           }},
          {"widgetId": "w2", "kind": "teleporter", "status": "ok", "payload": {"anything": true}}
        ]}
        """
        let data = try XCTUnwrap(json.data(using: .utf8))
        let response = try decoder.decode(DashboardResolveResponse.self, from: data)
        XCTAssertEqual(response.results.count, 2)

        let known = try XCTUnwrap(response.resultsByWidgetID["w1"])
        XCTAssertEqual(known.kind, .statTile)
        XCTAssertNotNil(known.payload)
        XCTAssertNil(known.decodeError)

        let unknown = try XCTUnwrap(response.resultsByWidgetID["w2"])
        XCTAssertNil(unknown.kind)
        XCTAssertNil(unknown.payload)
        XCTAssertEqual(unknown.effectiveStatus, .error)
        XCTAssertNotNil(unknown.failureMessage)
        XCTAssertTrue(unknown.failureMessage?.contains("teleporter") ?? false, "\(unknown.failureMessage ?? "")")
    }

    func testAPayloadThatCannotBeReadDegradesToOneFailedResult() throws {
        let json = """
        {"results": [
          {"widgetId": "w1", "kind": "leaderboard", "status": "ok", "payload": {"rows": "not an array"}}
        ]}
        """
        let data = try XCTUnwrap(json.data(using: .utf8))
        let response = try decoder.decode(DashboardResolveResponse.self, from: data)
        let result = try XCTUnwrap(response.results.first)
        XCTAssertNil(result.payload)
        XCTAssertEqual(result.effectiveStatus, .error)
        XCTAssertNotNil(result.decodeError)
    }
}
